import { realpath } from "node:fs/promises";
import { clearConfigCache, getConfig } from "../../config/index.js";
import { bindExecutorDiscoveryRoots } from "./executor-discovery-roots.js";
import { clearRegistryScope } from "../../registry/project-scoped-registry-manager.js";
import { tryGetRegistryScopeId } from "../../cache/cache-key-builder.js";
import { clearTranspileCache } from "../../discovery/transpiler.js";
import { discoverProjectAgentRuntime } from "../project/agent-runtime.js";
import { nodeAdapter } from "../../platform/adapters/node.js";
import { ExecutorDiscoveryError } from "./executor-discovery-schema.js";
import { tryResolve } from "../../extensions/contracts.js";
let activeOwner;
/** Executor-only default backend. Its module is loaded on the first metadata operation. */
export function createNodeExecutorDiscoveryBackend(input) {
    const owner = {};
    let claimed = false;
    return {
        async load(signal) {
            signal.throwIfAborted();
            // This backend owns a dedicated process's default registry namespace.
            // It does not invent an application project to obtain a registry scope.
            if (activeOwner || tryGetRegistryScopeId() !== null) {
                throw new ExecutorDiscoveryError("EXECUTOR_DISCOVERY_BUSY");
            }
            activeOwner = owner;
            claimed = true;
            const config = await getConfig(input.projectDir, nodeAdapter, { cacheKey: input.cacheKey });
            const projectDir = await realpath(input.projectDir);
            const boundConfig = await bindExecutorDiscoveryRoots(projectDir, config, realpath);
            signal.throwIfAborted();
            return discoverProjectAgentRuntime({
                projectDir,
                cacheKey: input.cacheKey,
                adapter: nodeAdapter,
                // Application storage configuration does not select the executor's
                // source filesystem. Preserve discovery paths/policy in a local copy.
                config: boundConfig,
                allowHostProjectCodeExecution: true,
            });
        },
        async cleanup() {
            if (!claimed)
                return;
            claimed = false;
            let failed = false;
            const bundler = tryResolve("Bundler");
            try {
                for (const clean of [
                    () => clearRegistryScope("__default__"),
                    clearTranspileCache,
                    clearConfigCache,
                ]) {
                    try {
                        clean();
                    }
                    catch {
                        failed = true;
                    }
                }
                try {
                    await bundler?.stop?.();
                }
                catch {
                    failed = true;
                }
            }
            finally {
                if (activeOwner === owner)
                    activeOwner = undefined;
            }
            if (failed)
                throw new ExecutorDiscoveryError("EXECUTOR_DISCOVERY_CLEANUP_FAILED");
        },
    };
}
